// The look finder ("Describe your vibe" on Explore): catalog.json's "finder"
// (generated by scripts/export-catalog.sh from AppCore's TemplateCatalog,
// StyleCatalog, EnhanceOption and GlowCam, plus the editor's effects listed
// in scripts/export-catalog), the JSON schema that holds Claude to those ids,
// and the check that drops anything else. An item is named "<kind>:<id>" to
// Claude and returned to the app as { kind, id }: a look and a style can share
// an id ("watercolor"), never a kind and an id.
import catalog from "../_shared/catalog.json" with { type: "json" };

export const FINDER_KINDS = ["look", "style", "effect", "enhance", "glow"] as const;
export type FinderKind = typeof FINDER_KINDS[number];

export interface FinderItem {
  id: string;
  name: string;
  about?: string;
  isPro: boolean;
  collection?: string;
  season?: string;
  cloud?: boolean;
}

interface FinderCatalog {
  looks: FinderItem[];
  styles: FinderItem[];
  effects: FinderItem[];
  enhance: FinderItem[];
  glow: FinderItem[];
}

const FINDER = (catalog as unknown as { finder: FinderCatalog }).finder;

/** Each kind's items, in the catalog's order. */
export const FINDER_ITEMS: Record<FinderKind, FinderItem[]> = {
  look: FINDER.looks,
  style: FINDER.styles,
  effect: FINDER.effects,
  enhance: FINDER.enhance,
  glow: FINDER.glow,
};

/** At most this many picks, each with a reason of at most MAX_REASON characters. */
export const MAX_PICKS = 3;
export const MAX_REASON = 100;

const key = (kind: FinderKind, id: string) => `${kind}:${id}`;

/** "<kind>:<id>" for every item of the given kinds. */
export function finderKeys(kinds: readonly FinderKind[] = FINDER_KINDS): string[] {
  return FINDER_KINDS.filter((kind) => kinds.includes(kind)).flatMap((kind) =>
    FINDER_ITEMS[kind].map((item) => key(kind, item.id))
  );
}

/** The answer's schema: up to 3 picks of the kinds she can use, each with a reason. */
export function finderSchema(kinds: readonly FinderKind[] = FINDER_KINDS): Record<string, unknown> {
  return {
    type: "object",
    properties: {
      picks: {
        type: "array",
        items: {
          type: "object",
          properties: {
            item: { type: "string", enum: finderKeys(kinds) },
            reason: { type: "string" },
          },
          required: ["item", "reason"],
          additionalProperties: false,
        },
      },
    },
    required: ["picks"],
    additionalProperties: false,
  };
}

/** The catalog for Claude, one line per item, by kind. The same for every request. */
export function finderCatalogText(): string {
  const line = (kind: FinderKind, item: FinderItem) => {
    const notes = [
      item.about,
      item.collection ? `collection ${item.collection}` : "",
      item.season ? `season ${item.season}` : "",
      item.cloud === false ? "free, on the device" : "",
      item.isPro ? "Pro" : "",
    ].filter(Boolean);
    return `- ${key(kind, item.id)} (${item.name})${notes.length ? `: ${notes.join("; ")}` : ""}`;
  };
  const section = (title: string, kind: FinderKind) => [title, ...FINDER_ITEMS[kind].map((item) => line(kind, item))];
  return [
    ...section("One-tap looks (an AI edit of her photo):", "look"),
    ...section("Create styles (a new picture made from words, in this style):", "style"),
    ...section("Free retro effects for her photo (on the device):", "effect"),
    ...section("Enhance (fixes for a photo):", "enhance"),
    ...section("Retro Cam's Glow looks (live in the camera; light and colour only):", "glow"),
  ].join("\n");
}

export interface FinderPick {
  kind: FinderKind;
  id: string;
  /** Her words' reason, as Claude wrote it (screened by the handler). */
  reason: string;
}

/**
 * The picks Claude made of the kinds she can use: known items only, each
 * once, in Claude's order. Reasons aren't checked here (the handler does).
 */
export function readFinderPicks(value: unknown, kinds: readonly FinderKind[]): FinderPick[] | undefined {
  const list = typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as { picks?: unknown }).picks
    : undefined;
  if (!Array.isArray(list)) return undefined;
  const allowed = new Set(finderKeys(kinds));
  const seen = new Set<string>();
  const picks: FinderPick[] = [];
  for (const entry of list) {
    if (typeof entry !== "object" || entry === null || Array.isArray(entry)) continue;
    const { item, reason } = entry as { item?: unknown; reason?: unknown };
    if (typeof item !== "string" || !allowed.has(item) || seen.has(item)) continue;
    seen.add(item);
    const split = item.indexOf(":");
    picks.push({
      kind: item.slice(0, split) as FinderKind,
      id: item.slice(split + 1),
      reason: typeof reason === "string" ? reason : "",
    });
  }
  return picks;
}
